{name:"daily/cat.md"},B=Object.assign(y,{setup(l){return(n,t)=>(r(),f("div",null,[t[0]||(t[0]=o('<h1 id="小猫" tabindex="-1">小猫 <a class="header-anchor" href="#小猫" aria-label="Permalink to &quot;小猫&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">没有做好足够的心理/经济准备，不要养猫。</p><p>因为养猫一养就是十几年，在各方面都不成熟的情况下，如果没有办法保证对另一个生命完全负责，不养对人对猫都是一种最好的选择。</p><p>当然，如果各方面都准备好，决定要养了，一定要记住的就是给猫吃好点、定期驱虫打疫苗，因为猫健健康康不生病的情况下开支是最小的！</p></div><h2 id="猫粮" tabindex="-1">猫粮 <a class="header-anchor" href="#猫粮" aria-label="Permalink to &quot;猫粮&quot;">​</a></h2><p>日进 40g - 60g</p><p>按 60g 计 1.8kg/month =&gt; 1.8kg * 60RMB/kg = 108RMB</p><table tabindex="0"><thead><tr><th style="text-align:left;">猫粮品牌</th><th style="text-align:left;">规格</th><th style="text-align:left;">每公斤价格 ￥/kg (常用规格)</th><th style="text-align:right;">食用情况</th></tr></thead><tbody><tr><td style="text-align:left;">美士 Nutro</td><td style="text-align:left;">成猫 三文鱼</td><td style="text-align:left;">64</td><td style="text-align:right;">完全不吃</td></tr><tr><td style="text-align:left;">素力高 Solid Gold</td><td style="text-align:left;">多种肉美毛</td><td style="text-align:left;">62.3</td><td style="text-align:right;">吃</td></tr><tr><td style="text-align:left;">素力高 Solid Gold</td><td style="text-align:left;">经典鸡肉</td><td style="text-align:left;">47.4 - 53</td><td style="text-align:right;">吃</td></tr><tr><td style="text-align:left;">皇家</td><td style="text-align:left;">幼猫 K36 4-12 月</td><td style="text-align:left;">44</td><td style="text-align:right;">吃 换了素力高后就再也不吃了</td></tr><tr><td style="text-align:left;">orijin</td><td style="text-align:left;">通用鸡肉味</td><td style="text-align:left;">107.4</td><td style="text-align:right;">-</td></tr><tr><td style="text-align:left;">halo 自然光环</td><td style="text-align:left;">成猫敏感肠胃海鲜味</td><td style="text-align:left;">69(10磅/4.5kg 309)</td><td style="text-align:right;">换着吃 一会吃鸡肉不吃鱼肉</td></tr><tr><td style="text-align:left;">halo 自然光环</td><td style="text-align:left;">成猫健美鸡肉味</td><td style="text-align:left;">69(10磅/4.5kg 309)</td><td style="text-align:right;">换着吃 一会吃鱼肉不吃鸡肉</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">群友 邓邓 推荐</p><p>猫粮我也是换过很多了，渴望，巅峰，go，草本魔力，rawz，爱肯拿，百利生鲜鸡，网易天成（吃了屎巨臭），还有 K9 冻干（一只猫的时候当主食，四只猫吃不起了）</p></div><h2 id="零食" tabindex="-1">零食 <a class="header-anchor" href="#零食" aria-label="Permalink to &quot;零食&quot;">​</a></h2><p>收录最低价</p><p>红狗各种营养膏 ¥40.25/120g ￥0.34/g<br> ￥24.33/58g ￥0.42/g</p><p>卫仕化毛膏 ￥36.92/120g ￥0.31/g</p><p>卫仕，猫多维，复合维生素片，￥56.42/240片</p><p>noloop 诺洛 冻干，鸭肉、鸡肉 ￥42.65/150g ￥8.53/30g(一袋)</p><h2 id="猫砂" tabindex="-1">猫砂 <a class="header-anchor" href="#猫砂" aria-label="Permalink to &quot;猫砂&quot;">​</a></h2><p>日耗 200g 6kg/month =&gt; 6kg * RMB12/kg = 72RMB</p>',15)),i(x),t[1]||(t[1]=o('<h2 id="驱虫" tabindex="-1">驱虫 <a class="header-anchor" href="#驱虫" aria-label="Permalink to &quot;驱虫&quot;">​</a></h2><p>双11一盒6支￥300</p><table tabindex="0"><thead><tr><th style="text-align:left;">驱虫品牌</th><th style="text-align:left;">规格</th><th style="text-align:left;">单支价格</th></tr></thead><tbody><tr><td style="text-align:left;">大宠爱</td><td style="text-align:left;">猫 2.6-7.5kg 蓝色体内外</td><td style="text-align:left;">50/54</td></tr></tbody></table><h2 id="玩具" tabindex="-1">玩具 <a class="header-anchor" href="#玩具" aria-label="Permalink to &quot;玩具&quot;">​</a></h2><p>todo</p><h2 id="记录" tabindex="-1">记录 <a class="header-anchor" href="#记录" aria-label="Permalink to &quot;记录&quot;">​</a></h2><h3 id="驱虫-1" tabindex="-1">驱虫 <a class="header-anchor" href="#驱虫-1" aria-label="Permalink to &quot;驱虫&quot;">​</a></h3><p>已推送手机日历</p><h3 id="洗澡" tabindex="-1">洗澡 <a class="header-anchor" href="#洗澡" aria-label="Permalink to &quot;洗澡&quot;">​</a></h3><p>2024 未洗澡<br> 2023 未洗澡</p>',10))]))}});export{R as __pageData,B as default};
